#!/usr/bin/env bash
# scripts/park-feed-markers.sh parks odoo-connect's and OpenELIS's feed
# bookmarks with SQL that must fit the tables each actually creates:
# id / feed_uri / last_read_entry_id / feed_uri_for_last_read_entry and
# NOTHING else. The Odoo 10 era table also carried create_date/write_date, and
# SQL written against it stops an install (column "write_date" does not exist).
# The three shared columns are the whole contract; they fit every shape.
# Task 080 and the upgrade's start step both park through the script; a feed
# with no entries has its bookmark removed (one copied from another OpenMRS
# would stop the job for good).
set -u
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
fails=0
ok_(){ printf '  ok   %s\n' "$1"; }
bad(){ printf '  FAIL %s\n' "$1"; fails=$((fails+1)); }
S="${HERE}/../../scripts/park-feed-markers.sh"
T80="${HERE}/../tasks/080-stack.sh"
block(){ awk -v n="$1" "/<<'SQL'/{c++; f=(c==n); next} /^SQL\$/{f=0} f" "$S"; }
park_sql="$(block 1)"; clear_sql="$(block 2)"
[ -n "$park_sql" ] && [ -n "$clear_sql" ] && ok_ "the script carries its park and clear SQL in two SQL heredocs" || bad "park/clear SQL heredocs not found in park-feed-markers.sh"
printf '%s\n%s' "$park_sql" "$clear_sql" | grep -qE 'write_date|create_date' && bad "marker SQL names create_date/write_date, which the Odoo 16 table lacks" || ok_ "marker SQL names only the three shared columns"
grep -q 'bash scripts/park-feed-markers.sh' "$T80" && ! grep -q 'UPDATE markers' "$T80" && ok_ "080 parks through the script and carries no marker SQL of its own" || bad "080 does not park through park-feed-markers.sh, or still carries marker SQL"
grep -q 'park odoo-connect odoo public "patient encounter lab saleable drug"' "$S" && grep -q 'park OpenELIS openelis clinlims "patient encounter lab"' "$S" \
  && ok_ "the script parks odoo-connect's five feeds and OpenELIS's three" || bad "park-feed-markers.sh does not name odoo-connect's five feeds and OpenELIS's three"

# Live proof against a real PostgreSQL when one is at hand (the dev box's
# Homebrew instance); a host without psql still gets the static guards above.
db="${MARKERS_TEST_DB:-bahmni_test}"
if command -v psql >/dev/null 2>&1 && psql -d "$db" -qAt -c 'select 1' >/dev/null 2>&1; then
  sch="mk_test_$$"; elis="mk_elis_$$"
  run(){ local s="$1"; shift; { printf 'SET search_path=%s;\n' "$s"; cat; } | psql -d "$db" -v ON_ERROR_STOP=1 -q -At -v f="$1" -v e="${2:-}" -v p="${3:-}"; }
  # the seed's own DDL: odoo-connect's (pg_dump of the hub's odoo database) and
  # OpenELIS's (clinlims.markers, its two position columns nullable)
  psql -d "$db" -q -v ON_ERROR_STOP=1 >/dev/null <<DDL
CREATE SCHEMA ${sch};
CREATE TABLE ${sch}.markers (id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, feed_uri_for_last_read_entry varchar(250) NOT NULL, feed_uri varchar(250) NOT NULL, last_read_entry_id varchar(250) NOT NULL);
INSERT INTO ${sch}.markers (feed_uri_for_last_read_entry, feed_uri, last_read_entry_id) VALUES ('old-page','http://openmrs:8080/openmrs/ws/atomfeed/drug/recent','old-entry');
INSERT INTO ${sch}.markers (feed_uri_for_last_read_entry, feed_uri, last_read_entry_id) VALUES ('http://openmrs:8080/openmrs/ws/atomfeed/saleable/48','http://openmrs:8080/openmrs/ws/atomfeed/saleable/recent','tag:the-hubs-entry');
CREATE SCHEMA ${elis};
CREATE TABLE ${elis}.markers (id serial PRIMARY KEY, feed_uri_for_last_read_entry varchar(250), feed_uri varchar(250) NOT NULL, last_read_entry_id varchar(250));
INSERT INTO ${elis}.markers (feed_uri_for_last_read_entry, feed_uri, last_read_entry_id) VALUES ('http://openmrs:8080/openmrs/ws/atomfeed/patient/67812','http://openmrs:8080/openmrs/ws/atomfeed/patient/recent','tag:the-hubs-entry');
DDL
  printf '%s\n' "$park_sql" | run "$sch" 'http://openmrs:8080/openmrs/ws/atomfeed/drug/recent' 'tag:new-drug' 'http://openmrs:8080/openmrs/ws/atomfeed/drug/599' >/dev/null 2>"/tmp/mk.$$" && ok_ "odoo-connect table: updates an existing row" || bad "update failed: $(cat "/tmp/mk.$$")"
  printf '%s\n' "$park_sql" | run "$sch" 'http://openmrs:8080/openmrs/ws/atomfeed/patient/recent' 'tag:new-patient' 'http://openmrs:8080/openmrs/ws/atomfeed/patient/7' >/dev/null 2>"/tmp/mk.$$" && ok_ "odoo-connect table: inserts a missing row" || bad "insert failed: $(cat "/tmp/mk.$$")"
  printf '%s\n' "$clear_sql" | run "$sch" 'http://openmrs:8080/openmrs/ws/atomfeed/saleable/recent' >/dev/null 2>"/tmp/mk.$$" && ok_ "odoo-connect table: removes the bookmark of an empty feed" || bad "clear failed: $(cat "/tmp/mk.$$")"
  got="$(psql -d "$db" -qAt -c "select feed_uri||'='||last_read_entry_id from ${sch}.markers order by 1" | tr '\n' ' ')"
  [ "$got" = "http://openmrs:8080/openmrs/ws/atomfeed/drug/recent=tag:new-drug http://openmrs:8080/openmrs/ws/atomfeed/patient/recent=tag:new-patient " ] && ok_ "odoo-connect table: one row per kept feed, at the new position; the empty feed's row is gone" || bad "odoo-connect rows are: $got"
  printf '%s\n' "$park_sql" | run "$elis" 'http://openmrs:8080/openmrs/ws/atomfeed/patient/recent' 'tag:clinic-patient' 'http://openmrs:8080/openmrs/ws/atomfeed/patient/67813' >/dev/null 2>"/tmp/mk.$$" && ok_ "OpenELIS table: replaces the hub's patient bookmark" || bad "OpenELIS update failed: $(cat "/tmp/mk.$$")"
  got="$(psql -d "$db" -qAt -c "select count(*)||':'||max(last_read_entry_id)||':'||max(feed_uri_for_last_read_entry) from ${elis}.markers where feed_uri like '%patient/recent'")"
  [ "$got" = "1:tag:clinic-patient:http://openmrs:8080/openmrs/ws/atomfeed/patient/67813" ] && ok_ "OpenELIS table: one patient bookmark, at this clinic's entry" || bad "OpenELIS rows: $got"
  psql -d "$db" -q -c "DROP SCHEMA ${sch} CASCADE; DROP SCHEMA ${elis} CASCADE" >/dev/null 2>&1; rm -f "/tmp/mk.$$"
else
  ok_ "live PostgreSQL proof skipped (no psql / no ${db})"
fi
exit "$fails"
